SELECT EXTRACT(YEAR FROM f.time) AS yr, COUNT(*) AS n_rows, COUNT(DISTINCT f.ticker) AS n_tk , ROUND(COUNTIF(f.ROIC3Y IS NULL)/COUNT(*),3) AS ROIC3Y, ROUND(COUNTIF(f.ROIC_Min3Y IS NULL)/COUNT(*),3) AS ROIC_Min3Y, ROUND(COUNTIF(f.ROE_Min3Y IS NULL)/COUNT(*),3) AS ROE_Min3Y, ROUND(COUNTIF(f.ROIC_Trailing IS NULL)/COUNT(*),3) AS ROIC_Trailing, ROUND(COUNTIF(f.ROIC5Y IS NULL)/COUNT(*),3) AS ROIC5Y, ROUND(COUNTIF(f.ROIC_Min5Y IS NULL)/COUNT(*),3) AS ROIC_Min5Y, ROUND(COUNTIF(f.ROE_Min5Y IS NULL)/COUNT(*),3) AS ROE_Min5Y, ROUND(COUNTIF(f.ROE3Y IS NULL)/COUNT(*),3) AS ROE3Y, ROUND(COUNTIF(f.ROE5Y IS NULL)/COUNT(*),3) AS ROE5Y, ROUND(COUNTIF(f.ROE_Trailing IS NULL)/COUNT(*),3) AS ROE_Trailing, ROUND(COUNTIF(f.Debt_Eq_P0 IS NULL)/COUNT(*),3) AS Debt_Eq_P0, ROUND(COUNTIF(f.Debt_Eq_P4 IS NULL)/COUNT(*),3) AS Debt_Eq_P4, ROUND(COUNTIF(f.STLTDebt_Eq_P0 IS NULL)/COUNT(*),3) AS STLTDebt_Eq_P0, ROUND(COUNTIF(f.STLTDebt_Eq_P4 IS NULL)/COUNT(*),3) AS STLTDebt_Eq_P4, ROUND(COUNTIF(f.FSCORE IS NULL)/COUNT(*),3) AS FSCORE, ROUND(COUNTIF(f.CF_OA_P0 IS NULL)/COUNT(*),3) AS CF_OA_P0, ROUND(COUNTIF(f.CF_OA_P3 IS NULL)/COUNT(*),3) AS CF_OA_P3, ROUND(COUNTIF(f.CF_OA_5Y IS NULL)/COUNT(*),3) AS CF_OA_5Y, ROUND(COUNTIF(f.NP_P0 IS NULL)/COUNT(*),3) AS NP_P0, ROUND(COUNTIF(f.NP_P4 IS NULL)/COUNT(*),3) AS NP_P4, ROUND(COUNTIF(f.NP_P7 IS NULL)/COUNT(*),3) AS NP_P7, ROUND(COUNTIF(f.GPM_P0 IS NULL)/COUNT(*),3) AS GPM_P0, ROUND(COUNTIF(f.GPM_P7 IS NULL)/COUNT(*),3) AS GPM_P7, ROUND(COUNTIF(f.Revenue_P0 IS NULL)/COUNT(*),3) AS Revenue_P0, ROUND(COUNTIF(f.Revenue_P7 IS NULL)/COUNT(*),3) AS Revenue_P7, ROUND(COUNTIF(f.UnearnRev_P0 IS NULL)/COUNT(*),3) AS UnearnRev_P0, ROUND(COUNTIF(f.totalAsset_P0 IS NULL)/COUNT(*),3) AS totalAsset_P0, ROUND(COUNTIF(f.PE IS NULL)/COUNT(*),3) AS PE, ROUND(COUNTIF(f.PCF IS NULL)/COUNT(*),3) AS PCF, ROUND(COUNTIF(f.PS IS NULL)/COUNT(*),3) AS PS, ROUND(COUNTIF(f.Release_Date IS NULL)/COUNT(*),3) AS Release_Date
FROM tav2_bq.ticker_financial AS f WHERE f.time BETWEEN '2008-01-01' AND '2015-12-31'
GROUP BY yr ORDER BY yr
